"""Login workflow and logoff functions. These functions are called from the top level
IntegrityService interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
import interops.libraries.integrity.pages.service_screen as ServicePgObj
import interops.libraries.integrity.pages.storedbeam_menu as StoredBeamPgObj
import interops.libraries.integrity.pages.clinical_screen as ClinicalPgObj
import interops.libraries.integrity.pages.login_screen as LoginPbObj
from interops.libraries.integrity.interactions import IntegrityCore
from interops.libraries.integrity.sub_system_workflows.general_utility_funcs import _utility_close_all_open_applets
import interops.libraries.icom.icom_th as IcomTest
from interops.libraries.desktop import AutManager
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
from interops.libraries.desktop import decorators as deco
import squishtest3 as sq
import logging


logger = logging.getLogger(__name__)

@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _login_check_current_user_and_clean_state(username: str, password: str) -> bool:
    #TODO - may need to refactor/ rewrite this when LoginScreen() and interactions/login.py are updated
    '''
    Checks if the correct user is already logged in before attempting
    to login again. If the current user is not as expected, logout
    and login as the specified user.

    If the current user already logged in is correct, clean up and
    exit all existing menus to return the system to a fresh login
    state.

    Args:
        username(str): Plainttext username
        password(str): Plainttext password

    Returns:
        bool - Login Success
    '''

    logger.info("login_as called with " + username + ", " + password)
    clean = StoredBeamPgObj.DeliverStoredBeam()
    exit_app = ServicePgObj.ServiceMenuBar()
    try:
        # Using real name here rather than symbolic so we don't need to add a symbolic name for each
        # possible login. Note the additional space before the username too
        # Changed to id as it was finding two elements and falling over
        sq.waitForObject({'text': ' ' + username, 'id': 1012}, 3000)
        logger.info("already logged in as " + username)
        '''close open applets'''
        return _utility_close_all_open_applets()

    except Exception as e:
        logger.info("Not logged in currently " + str(e))
        pass
    login_screen = LoginPbObj.LoginScreen()
    try:
        if login_screen.ready():
            login_screen.login_user(username, password)
        else:
            raise Exception("Login screen not ready. Try various scenarios to handle exiting of current states to return to login screen")

    except Exception:
        # Try to logout
        if not AutManager.is_aut_running(INTEGRITY_APP_NAME):
            return False
        if sq.object.exists(IntegrityObjects.dSB_Btn_UnConfirm):
            clean.press_unconfirm()
        if sq.object.exists(IntegrityObjects.dSB_Btn_NextBeam):
            clean.press_next_beam()

        if "service" in IntegrityCore.get_current_logged_in_username():
            if exit_app.log_off():
                try:
                    if login_screen.ready():
                        login_screen.login_user(username, password)
                    try:
                        sq.waitForObject({'text': ' ' + username, 'id': 1012}, 5000)
                        return True
                    except Exception:
                        return False
                except Exception:
                    pass

        rep = ClinicalPgObj.ReceiveExternalPrescription()
        try:
            rep.exit()
        except Exception:
            # try closing icom connection
            try:
                if AutManager.is_aut_running("iCOMCat:127.0.0.1:4322"):
                    icom = IcomTest.iCOM_cat()
                    icom.unconfirm_settings()
            except Exception:
                pass
            sq.snooze(2)
            try:
                rep.exit()
            except Exception:
                pass
        sq.snooze(2)

        exit_app.log_off()
        try:
            if login_screen.ready():
                login_screen.login_user(username, password)
        except Exception:
            return False

    popup_OK = "{container={type='Pane'} text='OK' type='Button'}"
    try:
        sq.mouseClick(sq.waitForObjectExists(popup_OK, 2500))
    except Exception:
        pass

    try:
        sq.waitForObject({'text': ' ' + username, 'id': 1012}, 20000)
        return True
    except Exception as e:
        logger.info("Not logged in after attempt: " + str(e))
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _log_off() -> bool:
    '''
    Log off via the Service Menu Bar.

    Returns:
        bool: True if log off succeeded
    '''
    logger.info("log_off called.")

    service_menu = ServicePgObj.ServiceMenuBar()
    return service_menu.log_off()